INSERT INTO feature VALUES('epics-workflow','workflow','An epic closes itself once its units close',NULL,'implemented','ordinary',NULL,'An epic is blocked by its units: `issue:file --epic` and a body line `Advances #n`, `Part of #n` or `from: #n` naming an open epic set it blocked by the new issue, `unit:check` refuses a unit naming an epic not blocked by it, and `epics:link` backfills the relation from body references. When an issue closes, the epics workflow reads each open epic it blocked or sat under, sets the epic blocked by each open sub-issue it is not yet blocked by, and closes the epic when its blocked-by issues and sub-issues number at least one and none is open, commenting `<!-- epic-closed -->` with them; an epic with no unit is never closed, and `report:deps` lists a ledger row owing on a closed issue, or only on an open epic.',NULL,'.config/epics/cases.json .config/epics/link.json .config/reports/report.json',NULL,NULL);
